-- 563: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 10 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_563_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_563_guard;
INSERT INTO _migration_563_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_037' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a negative effect of globalization on Ghanaian culture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The erosion of local languages and customs as foreign lifestyles dominate the youth","B. Faster communication with relatives abroad","C. Wider export markets for Ghanaian products","D. Easier access to global information and technology"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Constant exposure to foreign media and lifestyles leads many young Ghanaians to abandon mother tongues, dress and customs, weakening cultural identity. Faster communication, wider markets and easier information access are widely recognized benefits of globalization, so they cannot answer a question about its negative effects. Therefore the correct answer is A: The erosion of local languages and customs as foreign lifestyles dominate the youth.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_037' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_563_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_038' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The spread of cultural traits such as music, dress styles and foods from one society to another is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ethnocentrism","B. Cultural diffusion","C. Enculturation","D. Cultural conflict"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Cultural diffusion is the transmission of cultural elements between societies — for example the spread of hiplife rhythms or foreign fast food. Ethnocentrism is judging other cultures by the standards of one’s own, enculturation is learning one’s own culture from birth, and cultural conflict is a clash between incompatible cultural values. Therefore the correct answer is B: Cultural diffusion.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_038' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_563_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_039' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Traditional festivals in Ghana contribute to national development mainly by...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Replacing the work of Metropolitan and District Assemblies","B. Providing free housing for community members","C. Promoting unity and attracting tourists whose spending supports local economies","D. Reducing the country’s national debt directly"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Festivals such as Aboakyir and Hogbetsotso reunite families and clans, settle disputes and draw domestic and foreign tourists whose spending boosts hospitality, transport and crafts. Assemblies remain responsible for local administration, and festivals neither build houses nor pay down sovereign debt. Therefore the correct answer is C: Promoting unity and attracting tourists whose spending supports local economies.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_039' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_563_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_040' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A global citizen is best described as a person who...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Holds the citizenship of many different countries","B. Travels abroad frequently on business","C. Completely rejects his or her own culture","D. Identifies with the wider world community and acts on global issues while respecting local cultures"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Global citizenship is an outlook: awareness of worldwide interdependence, concern for issues such as climate change and human rights, and respect for diversity — not a legal status. Multiple passports and frequent travel are neither necessary nor sufficient, and rejecting one’s own culture contradicts the respect for diversity the concept requires. Therefore the correct answer is D: Identifies with the wider world community and acts on global issues while respecting local cultures.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_040' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_037', 'topic_wassce_p2_soc_cul', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a negative effect of globalization on Ghanaian culture?', 'multiple_choice', NULL, '["A. The erosion of local languages and customs as foreign lifestyles dominate the youth","B. Faster communication with relatives abroad","C. Wider export markets for Ghanaian products","D. Easier access to global information and technology"]', 'A', 'Constant exposure to foreign media and lifestyles leads many young Ghanaians to abandon mother tongues, dress and customs, weakening cultural identity. Faster communication, wider markets and easier information access are widely recognized benefits of globalization, so they cannot answer a question about its negative effects. Therefore the correct answer is A: The erosion of local languages and customs as foreign lifestyles dominate the youth.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_038', 'topic_wassce_p2_soc_cul', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The spread of cultural traits such as music, dress styles and foods from one society to another is known as...', 'multiple_choice', NULL, '["A. Ethnocentrism","B. Cultural diffusion","C. Enculturation","D. Cultural conflict"]', 'B', 'Cultural diffusion is the transmission of cultural elements between societies — for example the spread of hiplife rhythms or foreign fast food. Ethnocentrism is judging other cultures by the standards of one’s own, enculturation is learning one’s own culture from birth, and cultural conflict is a clash between incompatible cultural values. Therefore the correct answer is B: Cultural diffusion.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec');
