INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_040', 'topic_wassce_p2_soc_cul', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'A global citizen is best described as a person who...', 'multiple_choice', NULL, '["A. Holds the citizenship of many different countries","B. Travels abroad frequently on business","C. Completely rejects his or her own culture","D. Identifies with the wider world community and acts on global issues while respecting local cultures"]', 'D', 'Global citizenship is an outlook: awareness of worldwide interdependence, concern for issues such as climate change and human rights, and respect for diversity — not a legal status. Multiple passports and frequent travel are neither necessary nor sufficient, and rejecting one’s own culture contradicts the respect for diversity the concept requires. Therefore the correct answer is D: Identifies with the wider world community and acts on global issues while respecting local cultures.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
